    def get_subcells_info(self, timeout=10):
        """
        Get Subcell data of all available cells. Only supports 5G (NR).

        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If 5G subcell data is not provided by M-Plane.
        :raise DataInconsistent: If 5G ADMIN or OAM Node-B provided information is incorrect with expected or faulty.
        :return dict: Dict structure where Key is cell group name and Value is structure with Realtime and Hardware
                                information for cells.

        Example of returned data:

        ::

        {
            u'NRCELLGRP-0': {
                u'NRCELL-1': {
                    'NRCELL_L': {
                         'distName': '/MRBTS-1/RAT-1/NRTS-1/NRBTS_L-1/NRCELL_L-1',
                         'parameters': {'lcrId': 1,
                                        'nrCellIdentity': 16385,
                                        'nrCellgrpDN': u'/MRBTS-1/RAT-1/NRTS-1/NRBTS_L-1/NRCELLGRP_L-0',
                                        'administrativeState': u'Locked',
                                        'availabilityStatus': None,
                                        'operationalState': u'Disabled',
                                        'usageState': u'Idle'}
                                        }
                    },
                    'NRCELL_R': {
                          'distName': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-1/NRCELL_R-1',
                          'parameters': {'availabilityStatus': None,
                                         'bbModDNList': [],
                                         'frRefList': [],
                                         'nrCellIdentity': None,
                                         'operationalState': u'disabled',
                                         'proceduralStatus': None,
                                         'administrativeState': u'Unlocked',
                                         'blockingState': u'Unblocked',
                                         'usageState': u'Idle'}
                                        }
                    }
                }
            }
        }

        """
        bts_info = self.get_bts_info(timeout=timeout)

        if not bts_info.get("cellsGroup"):
            raise DataNotAvailable("Cell Group data containing subcell information was not provided by Node B OAM.")

        try:
            cell_groups_info = self.__get_cell_data_structure(cell_group_info=bts_info["cellsGroup"])
        except (KeyError, TypeError) as e:
            error_msg = "BTS cellsGroup information provided by OAM Node-B is inconsistent, or faulty. Error {}"
            raise DataInconsistent(error_msg.format(e))

        nr_cells_runtime = self.__get_infomodel_objects(
            object_type=NrCellRuntime,
            object_class_name="NRCELL_R",
            timeout=timeout)
        nr_cells_hardware = self.__get_infomodel_objects(
            object_type=NrCellHardware,
            object_class_name="NRCELL_L",
            timeout=timeout)

        self.__assign_hardware_cells(nr_cells_hardware, cell_groups_info)
        self.__assign_realtime_cells(nr_cells_runtime, cell_groups_info)

        return cell_groups_info

    def __assign_hardware_cells(self, nr_cells_hardware, cell_groups_info):
        for nr_cell in nr_cells_hardware:
            cell_group = InfoModelDistName(dist_name=nr_cell.nr_cellgrp_dn)
            self.__put_nr_cell_in_group(nr_cell, cell_groups_info, cell_group_name=cell_group.conf_name)

    def __assign_realtime_cells(self, nr_cells_runtime, cell_groups_info):
        for nr_cell in nr_cells_runtime:
            cell_group_name = self.__get_group_name_for_cell(
                cell_name=nr_cell.conf_name,
                cell_groups_info=cell_groups_info)
            if cell_group_name is None:
                error_msg = "Cell {cell_dist_name} returned by Node-B OAM, does not belong to any cell group"
                raise DataInconsistent(error_msg.format(cell_dist_name=nr_cell.dist_name))
            self.__put_nr_cell_in_group(nr_cell, cell_groups_info, cell_group_name=cell_group_name)

    def __get_group_name_for_cell(self, cell_name, cell_groups_info):
        for group_name, group_cells in cell_groups_info.items():
            if cell_name in group_cells:
                return group_name

    def __put_nr_cell_in_group(self, cell, cell_info, cell_group_name):
        cell_info[cell_group_name][cell.conf_name][cell.class_name] = cell.to_dict()

    def __get_cell_data_structure(self, cell_group_info):
        structure = {}
        for cell_group in cell_group_info:
            cell_group_name = cell_group["name"]

            if cell_group_name not in structure:
                structure[cell_group_name] = {}

            for cell_name in cell_group["nrCellList"]:
                structure[cell_group_name][cell_name] = {}

        return structure

    def __get_infomodel_objects(self, object_type, object_class_name, timeout):
        objects = []
        object_datas = self.get_managed_objects(class_name=object_class_name, timeout=timeout)

        for data in object_datas:
            objects.append(object_type.from_object_dict(data=data))
        return objects

    def get_subcells_status(self, timeout=10):
        """
        Get statuses for all subcells in cell groups.

        :param int timeout: Timeout for the operation.
        :raise DataNotAvailable: If 5G subcell data is not provided by M-Plane.
        :raise DataInconsistent: If 5G ADMIN or OAM Node-B provided information is incorrect with expected or faulty.
        :return dict: Dict structure where Key is cell group name and Value is structure with Realtime and Hardware
                                status names for cells.

        Example

        ::

        {
            u'NRCELLGRP-0': {
                u'NRCELL-1': {
                    'NRCELL_L': {
                        'administrativeState': u'Locked',
                        'availabilityStatus': None,
                        'operationalState': u'Disabled',
                        'usageState': u'Idle'
                    },
                    'NRCELL_R': {
                        'administrativeState': u'Unlocked',
                        'availabilityStatus': u'Failed',
                        'blockingState': u'Unblocked',
                        'operationalState': u'Disabled',
                        'usageState': u'Idle'
                    }
                }
            }
        }
        """
        cells_info = self.get_subcells_info(timeout=timeout)
        cells_statuses = {}

        try:
            for cell_group_name, cell_group_data in cells_info.items():
                cells_statuses[cell_group_name] = {}
                for cell_name, cell_data in cell_group_data.items():
                    cell_statuses = self.__get_statuses_for_cell(cell_data=cell_data)
                    cells_statuses[cell_group_name][cell_name] = cell_statuses

        except KeyError as e:
            raise DataInconsistent("Data provided by M-plane is inconsistent or faulty. Error {}".format(e))

        return cells_statuses

    def __get_statuses_for_cell(self, cell_data):
        cell_statuses = {}

        for cell_info_type, cell_type_data in cell_data.items():
            cell_statuses[cell_info_type] = cell_type_data["parameters"]

        return cell_statuses

    def start_5g_uplink_ccm_test_pucch(self, dist_name, interval, beam_pattern_id, receiving_slot,
                                       expectation_slot, pucch_format, ru_mode,
                                       phys_cell_id, format3_additional_dmrs,
                                       prb_offset, largest_prb_index, num_pucch_symbol,
                                       num_payload_bit, pucch_payload_content,
                                       nrarfcn_ul=None, nrarfcn_dl=None,
                                       timeout=60, **kwargs):
        """
        Starts 5G `Pucch` Performance CCM Test (start5GUplinkCCMTest).

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param float interval: Reporting time interval [0.1..3600] (step 0.1)
        :param List[int] beam_pattern_id: [0..1200].
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].
        :param int receiving_slot: [0..1023].
        :param int expectation_slot: [0..1023].
        :param str pucch_format: Either `F0` or `F2`. (from version admin20b also values: `F1` and `F3`).
        :param int nrarfcn_ul: (Optional) [0..3279165].
        :param int nrarfcn_dl: (Optional) [0..3279165].
        :param str format3_additional_dmrs: `Disabled` | `Enabled`
        :param int prb_offset: [0..272]
        :param int largest_prb_index: [0..272]
        :param int num_pucch_symbol: [0..255]
        :param int num_payload_bit: [0..255]
        :param int pucch_payload_content: [0..4294967295]
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param AdminConnection connection: AdminConnection object or if used, string name alias.
        :return: It returns dict with data.

        Example response

        ::

            {
              "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0",
              "confirmationNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/ACK-1",
                 "parameters": {}
              },
              "resultNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/NR_TEST_RESULT-1",
                 "parameters": {
                    "status": "Succeeded"
                 }
              }
           }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-start5GUplinkCCMTest.html

        """

        PERFORMANCE_TEST_TYPE = "Pucch"

        pucch_schema = CCMUplinkPucch(nrcell_rdn=dist_name, nrarfcn_ul=nrarfcn_ul, reporting_time_interval=interval,
                                      beam_pattern_id=beam_pattern_id, ru_mode=ru_mode, phys_cell_id=phys_cell_id,
                                      performance_test_type=PERFORMANCE_TEST_TYPE,
                                      receiving_slot=receiving_slot, expectation_slot=expectation_slot,
                                      pucch_format=pucch_format, format3_additional_dmrs=format3_additional_dmrs,
                                      prb_offset=prb_offset, largest_prb_index=largest_prb_index,
                                      num_pucch_symbol=num_pucch_symbol, num_payload_bit=num_payload_bit,
                                      pucch_payload_content=pucch_payload_content,
                                      nrarfcn_dl=nrarfcn_dl
                                      )

        parameters = pucch_schema.as_dict()

        return self._api_client.execute_procedure('start5GUplinkCCMTest',
                                                  parameters, timeout)

    def start_uplane_l1_trace(self, source_ip, dscp, destination_ip, destination_port,
                              nr_cell_dn, traces, output_mode, timeout=10, detailed_output=False):
        """
        .. note::
            SUPPORTS CUSTOMER API ONLY

        :param str source_ip: eg. "10.12.10.102"
        :param int dscp: eg. 1
        :param str destination_ip: eg. "10.12.10.102"
        :param int destination_port: eg. 1025
        :param str nr_cell_dn: eg. "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-1/NRCELL_R-1"
        :param list[dict] traces: list of dictionaries with keys:
                                                                int subType: eg. 1 [0..32767]
                                                                int traceId: eg. 1 [0..32767]
                                                                int nbReports: eg. 1 [0..32767]
        :param str output_mode: One of 'HistoryBuffer' or 'StreamingAndHistoryBuffer'
        :param Union[int,str] timeout: (optional) Timeout for the operation, defaults to 10.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return str: status 'Succeeded', 'Rejected' or 'Failed'
            or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-startUPlaneL1Trace.html
        """

        for trace in traces:
            try:
                params = {'subType': int(trace['subType']),
                          'traceId': int(trace['traceId']),
                          'nbReports': int(trace['nbReports'])}
            except KeyError:
                msg = "There is no required key in trace dictionary. Please consult the documentation: " \
                      "https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/{}".\
                    format("tutorial-startUPlaneL1Trace.html")
                raise KeyError(msg)

            subType = (0 <= params['subType'] <= 32767)
            traceId = (0 <= params['traceId'] <= 32767)
            nbReports = (0 <= params['nbReports'] <= 32767)

            params_to_check = {'subType': subType, 'traceId': traceId, 'nbReports': nbReports}
            self._check_params(params_to_check, params, "tutorial-startUPlaneL1Trace.html")

        if output_mode not in ("HistoryBuffer", "StreamingAndHistoryBuffer"):
            raise_value_error(param="output_mode",
                              value=str(output_mode),
                              subpage="tutorial-startUPlaneL1Trace.html")

        parameters = {
            "configurationParameters": {
                "sourceIp": source_ip,
                "dscp": dscp,
                "destinationIp": destination_ip,
                "destinationPort": destination_port,
            },
            "cellDN": nr_cell_dn,
            "traces": traces,
            "outputMode": output_mode
        }
        response = self._api_client.execute_customer_procedure(name='startUPlaneL1Trace',
                                                               parameters=parameters,
                                                               timeout=timeout
                                                               )
        return response if detailed_output else response.get(self._provided_content.request_message)

    def _check_params(self, params_to_check, params, subpage):
        for param in params_to_check:
            if params_to_check[param] is False:
                raise_value_error(param=param,
                                  value=str(params[param]),
                                  subpage=subpage)

