    def start_5g_uplink_ccm_test_pusch(self, dist_name, interval, beam_pattern_id,
                                       frc_index, prb_offset, digital_out_type,
                                       digital_out_rate, ul_dmrs_mapping_type, is_ptrs_fr2_enabled,
                                       ru_mode, phys_cell_id,
                                       bb_selector=None, nrarfcn_ul=None, nrarfcn_dl=None, num_uci_bits=None,
                                       csi_payload_bit=None, timeout=60, **kwargs):
        """
        Starts 5G `Pusch` Performance CCM Test (start5GUplinkCCMTest).

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param float interval: Reporting time interval [0.1..3600] (step 0.1)
        :param List[int] beam_pattern_id: [0..1200].
        :param str frc_index: One of the following:
                                'G_FR1_A3_8' | 'G_FR1_A3_9' | 'G_FR1_A3_10' | 'G_FR1_A3_12' | 'G_FR1_A3_13' | 'G_FR1_A3_14' |
                                'G_FR1_A3_22' | 'G_FR1_A3_23' | 'G_FR1_A3_24' | 'G_FR1_A3_26' | 'G_FR1_A3_27' | 'G_FR1_A3_28' |
                                'G_FR1_A3_31' | 'G_FR1_A3_32' | 'G_FR1_A4_8' | 'G_FR1_A4_9' | 'G_FR1_A4_10' | G_FR1_A4_11 |
                                'G_FR1_A4_12' | 'G_FR1_A4_13' | 'G_FR1_A4_14' | 'G_FR1_A4_22' | 'G_FR1_A4_23' | 'G_FR1_A4_24' |
                                'G_FR1_A4_26' | 'G_FR1_A4_27' | 'G_FR1_A4_28' | 'G_FR1_A5_8' | 'G_FR1_A5_9' | 'G_FR1_A5_10' |
                                'G_FR1_A5_12' | 'G_FR1_A5_13' | 'G_FR1_A5_14' | 'G_FR2_A3_4' | 'G_FR2_A3_9' | 'G_FR2_A3_16' |
                                'G_FR2_A3_21' | 'G_FR2_A4_4' | 'G_FR2_A4_9' | 'G_FR2_A4_14' | 'G_FR2_A4_19' | 'G_FR2_A5_4' |
                                'G_FR2_A5_9' | 'G_FR1_A1_2' | 'G_FR1_A1_5' | 'G_FR1_A2_5' | 'G_FR1_A1_1' | 'G_FR1_A1_4' |
                                'G_FR1_A2_4' | 'G_FR1_A4_31' | 'G_FR1_A4_31A' | 'G_FR1_A4_32' | 'G_FR1_A4_32A' |
                                'G_FR1_A3_34' | 'G_FR1_A4_30' | 'G_FR2_A7_4' | 'G_FR2_A7_9' | 'G_FR1_A3_34A' | 'G_FR1_A4_30A'
        :param int prb_offset: [0..273].
        :param str digital_out_type: Either `SerialKeysight` or `SerialRs`.
        :param str digital_out_rate: Either `Bitrate_115dot2K`,
                                     `Bitrate_1dot92M` or `Bitrate_460dot8K`.
        :param str ul_dmrs_mapping_type: "A" or "B".
        :param bool is_ptrs_fr2_enabled.
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].
        :param int bb_selector: (Optional) [0..3].
        :param int nrarfcn_ul: (Optional) [0..3279165].
        :param int nrarfcn_dl: (Optional) [0..3279165].
        :param int num_uci_bits: (Optional) [0.255].
        :param list[int] csi_payload_bit: (Optional, two items at most) list of integers [0..4294967295]
        :param int timeout: (optional) Timeout for the operation.
        :return: It returns dict with data.

        Example response

        ::
            {
                "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0",
                "confirmationNode": {
                    "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/ACK-1",
                    "parameters": {}
                },
                "resultNode": {
                    "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/NR_TEST_RESULT-1",
                    "parameters": {
                        "status": "Succeeded"
                    }
                }
            }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-start5GUplinkCCMTest.html

        """
        if not isinstance(is_ptrs_fr2_enabled, bool):
            raise ValueError('Parameter is_ptrs_fr2_enabled should be bool True or False not {}'
                             .format(type(is_ptrs_fr2_enabled)))

        PERFORMANCE_TEST_TYPE = "Pusch"
        pusch_schema = CCMUplinkPusch(nrcell_rdn=dist_name, nrarfcn_ul=nrarfcn_ul, reporting_time_interval=interval,
                                      beam_pattern_id=beam_pattern_id, performance_test_type=PERFORMANCE_TEST_TYPE,
                                      frc_index=frc_index, prb_offset=prb_offset, digital_out_type=digital_out_type,
                                      digital_out_rate=digital_out_rate, ul_dmrs_mapping_type=ul_dmrs_mapping_type,
                                      is_ptrs_fr2_enabled=is_ptrs_fr2_enabled, ru_mode=ru_mode,
                                      phys_cell_id=phys_cell_id, bb_selector=bb_selector, nrarfcn_dl=nrarfcn_dl,
                                      num_uci_bits=num_uci_bits, csi_payload_bit=csi_payload_bit
                                      )
        parameters = pusch_schema.as_dict()

        return self._api_client.execute_procedure('start5GUplinkCCMTest',
                                                  parameters, timeout)

    def start_rf_diagnostic_test(self,
                                 force_act_remote_rf_diag,
                                 cells,
                                 cell_type,
                                 rf_power_error_high_threshold,
                                 rf_power_error_low_threshold,
                                 tx_antenna_vswr_high_threshold,
                                 rx_antenna_rtwp_low_threshold,
                                 rx_antenna_rtwp_high_threshold,
                                 band_class=None,
                                 total_rf_power_high_threshold=None,
                                 total_rf_power_low_threshold=None,
                                 timeout=120,
                                 optional_band_thresholds=None,
                                 **kwargs):
        """
        Start RF diagnostic test.

        :param bool force_act_remote_rf_diag:  force_act_remote_rf_diag
        :param list cells: cells list
        :param string cell_type: type of cell <"LTE" | "NR">
        :param float rf_power_error_high_threshold: RF power error high threshold
        :param float rf_power_error_low_threshold: RF power error low threshold
        :param float tx_antenna_vswr_high_threshold: tx antenna VSWR high threshold
        :param float rx_antenna_rtwp_low_threshold: rx antenna RTWP low threshold
        :param float rx_antenna_rtwp_high_threshold: rx antenna RTWP high threshold
        :param integer band_class: band class - optional prohibited for NR cells
        :param float total_rf_power_high_threshold: total RF power high threshold - optional prohibited for NR cells
        :param float total_rf_power_low_threshold: total RF power low threshold - optional prohibited for NR cells
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param list optional_band_thresholds: should be given in order:
               band_class_x (int), total_rf_power_high_threshold_x (float), total_rf_power_low_threshold_x (float)
        :param float rx_antenna_rssi_low_threshold: rx antenna RSSI low threshold (passed via **kwargs)
        :param float rx_antenna_rssi_high_threshold: rx antenna RSSI high threshold (passed via **kwargs)

        :rtype: list
        :return: RF test result

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-rfDiagnosticTest.html
        """

        if cell_type not in ("LTE", "NR"):
            raise_value_error(param="cell_type",
                              value=str(cell_type),
                              subpage="tutorial-rfDiagnosticTest.html")

        force_act_remote_rf_diag = bool(force_act_remote_rf_diag)
        cells = convert_str_with_integers_to_list_of_int(cells)
        rf_power_error_high_threshold = float(rf_power_error_high_threshold)
        rf_power_error_low_threshold = float(rf_power_error_low_threshold)
        tx_antenna_vswr_high_threshold = float(tx_antenna_vswr_high_threshold)
        rx_antenna_rtwp_low_threshold = float(rx_antenna_rtwp_low_threshold)
        rx_antenna_rtwp_high_threshold = float(rx_antenna_rtwp_high_threshold)

        band_class = self._to_int_if_exist(band_class)
        total_rf_power_high_threshold = self._to_float_if_exist(total_rf_power_high_threshold)
        total_rf_power_low_threshold = self._to_float_if_exist(total_rf_power_low_threshold)
        if optional_band_thresholds:
            check_if_number_of_optional_args_is_divisible(3, optional_band_thresholds)
        band_rf_test_thresholds = self._band_rf_test_thresholds_calculation(band_class, total_rf_power_high_threshold,
                                                                            total_rf_power_low_threshold,
                                                                            optional_band_thresholds)

        thresholds = {"rFPowerErrorHighThreshold": rf_power_error_high_threshold,
                      "rFPowerErrorLowThreshold": rf_power_error_low_threshold,
                      "txAntennaVSWRHighThreshold": tx_antenna_vswr_high_threshold,
                      "rxAntennaRTWPHighThreshold": rx_antenna_rtwp_high_threshold,
                      "rxAntennaRTWPLowThreshold": rx_antenna_rtwp_low_threshold}

        if band_rf_test_thresholds:
            thresholds['bandRfTestThresholds'] = band_rf_test_thresholds

        rssi_low = kwargs.get("rx_antenna_rssi_low_threshold")
        rssi_high = kwargs.get("rx_antenna_rssi_high_threshold")

        if rssi_low:
            thresholds['rxAntennaRSSILowThreshold'] = float(rssi_low)
        if rssi_high:
            thresholds['rxAntennaRSSIHighThreshold'] = float(rssi_high)

        parameters = {
            "forceActRemoteRfDiag": force_act_remote_rf_diag,
            "cells": cells,
            "cellType": cell_type,
            "thresholds": thresholds,
        }
        return self._api_client.execute_customer_procedure("rfDiagnosticTest", parameters, timeout)

    def _band_rf_test_thresholds_calculation(self, band_class, total_rf_power_high_threshold,
                                             total_rf_power_low_threshold, optional_band_thresholds):
        band_rf_test_thresholds = []
        if any([band_class, total_rf_power_high_threshold, total_rf_power_low_threshold]):
            band_rf_test_thresholds = [{
                "bandClass": band_class,
                "totalRFPowerHighThreshold": total_rf_power_high_threshold,
                "totalRFPowerLowThreshold": total_rf_power_low_threshold,
            }]

        if optional_band_thresholds:
            for i in range(0, len(optional_band_thresholds) - 1, 3):
                band_rf_test_thresholds.append({
                    "bandClass": int(optional_band_thresholds[i]),
                    "totalRFPowerHighThreshold": float(optional_band_thresholds[i + 1]),
                    "totalRFPowerLowThreshold": float(optional_band_thresholds[i + 2]),
                })
        return band_rf_test_thresholds

    def _to_int_if_exist(self, value):
        if value:
            return int(value)

    def _to_float_if_exist(self, value):
        if value:
            return float(value)
